test('invoiceTotals sums line totals into subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 9500 + 3 * 6000);
  assert.equal(totals.total, 5 * 9500 + 3 * 6000);
});

